entries[406516] = { ["name"] = "Schreckensrisse", ["text"] = "Unbegrenzte Reichweite\nWirken in 1.5 sek.\nKazzara stößt ein wutentbranntes Brüllen aus, das bei mehreren Spielercharakteren ein brennendes Mal auslöst. Nach 5 Sek. öffnen sich andersweltliche Risse unter diesen Spielercharakteren in einem Sturm aus Schreckensfeuer. Verursacht 214878 Schattenflammenschaden innerhalb von 5 Metern.\n\nKazzaras freigelegter Kern veranlasst ' Schreckensrisse ', einen zusätzlichen Spielercharakter für jedes Rüstungsteil anzuvisieren, das ihr abgeschlagen wurde." }
entries[406517] = { ["name"] = "Schreckensriss", ["text"] = "Unbegrenzte Reichweite\nSofort\nKazzara stößt ein wutentbranntes Brüllen aus, das bei mehreren Spielercharakteren ein brennendes Mal auslöst. Nach 5 Sek. öffnen sich andersweltliche Risse unter diesen Spielercharakteren in einem Sturm aus Schreckensfeuer. Verursacht 214878 Schattenflammenschaden innerhalb von 5 Metern.\n\nKazzaras freigelegter Kern veranlasst ' Schreckensrisse ', einen zusätzlichen Spielercharakter für jedes Rüstungsteil anzuvisieren, das ihr abgeschlagen wurde." }
