entries[406527] = { ["name"] = "Der Große", ["text"] = "50 Meter Reichweite\nWirken in 1 sek.\nDer Zaubernde fixiert sich auf ein zufälliges Ziel und verfolgt es dann, während er die Dicke trägt.\n\nWenn der Zaubernde sein Ziel erreicht oder die Zeit abläuft, explodiert die Dicke. Getroffene Ziele erleiden 40 Feuerschaden." }
entries[406528] = { ["name"] = "Temporalessenz", ["text"] = "120 Meter Reichweite\nSofort\nDer entleerte Schwurstein setzt Partikel von Temporalessenz frei, die langsam zu ihm zurückkehren. Alle Partikel, die ihn erreichen, werden von Tyr absorbiert, wodurch die Absorption von ' Strahlende Barriere ' erhöht wird.\n\nSpielercharaktere können Temporalessenz einsammeln, um ' Gestohlene Zeit ' zu erhalten." }
