entries[406646] = { ["name"] = "Templerstöße", ["text"] = "'Kreuzfahrerstoß' wird zur zweiteiligen Combo.\n\n'Templerstoß' schlitzt einen Gegner für (121.993% der Angriffskraft) [ Klingen des Lichts : Heiligschlag / Strahlen]schaden auf und wird 5 Sek. lang durch 'Templerschlitzer' ersetzt.\n\n'Templerschlitzer' schlägt für (225.01% der Angriffskraft) [ Klingen des Lichts : Heiligschlag / Strahlen]schaden auf einen Gegner ein und verbrennt ihn für 50% des im Verlauf von 4 Sek. verursachten Schadens." }
entries[406647] = { ["name"] = "Templerschlitzer", ["text"] = "0.4% von Grundmana Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nSchließt die Templercombo ab, schlitzt das Ziel für [(225.01% der Angriffskraft) * 1 ] [ Klingen des Lichts : Heiligschlag / Strahlen]schaden auf und verbrennt es 4 Sek. lang für 50% des verursachten Schadens.\n\nErzeugt 1 Heilige Kraft." }
