entries[407027] = { ["name"] = "Korrosiver Ausstoß", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie Verseuchung von Galakrond schleudert eine Schlammsalve hervor, fügt allen Spielercharakteren innerhalb von 4 Metern um den Einschlagsbereich 6061123 Naturschaden zu und betäubt sie für 1.5 Sek." }
entries[407028] = { ["name"] = "Klebrige Teerbombe", ["text"] = "1.5% von Grundmana 40 Meter Reichweite\nSofort 45 sek. Abklingzeit\nWirft eine klebrige Teerbombe, die die Waffen Eures Ziels mit Teer bedeckt und es für 4 Sek. entwaffnet.\n\nNach 4 Sek. explodiert die klebrige Teerbombe und trifft Gegner in der Nähe. Andere Gegner, die von der Explosion getroffen werden, sind ebenfalls von 'Klebrige Teerbombe' betroffen, doch dieser Effekt kann sich nicht weiter ausbreiten." }
