entries[407036] = { ["name"] = "In der Leere verborgen", ["text"] = "Sofort\nDie Stimme aus dem Jenseits hüllt sich in Schatten und absorbiert 543645 Schaden. Solange der Schild hält, verbirgt sie sich vor Spielercharakteren, die nicht von ' Verderbnis ' betroffen sind. Sobald der Schild durchbrochen wird, beginnt die Stimme aus dem Jenseits, ' Gerissener Schleier ' einzusetzen." }
