entries[407048] = { ["name"] = "Sich der Verderbnis hingeben", ["text"] = "Sofort\nNeltharion ergibt sich der Dunkelheit. Fügt allen Spielercharakteren alle 1 Sek. 47751 Schattenschaden und am Ende der Kanalisierung allen Spielercharakteren 143252 Schattenschaden durch eine letzte Explosion zu.[] [\nNeltharion belegt mehrere Spielercharaktere mit ' Verderbnis '.]" }
