entries[407053] = { ["name"] = "Lebende Zündschnur", ["text"] = "100 Meter Reichweite\nSofort\nDer Zaubernde bricht in Flammen aus und fügt Gegnern in der Nähe 25 Feuerschaden zu.\n\nDann verwandelt der Zaubernde Gegner in lebende Zündschnüre und schickt ihnen explosive Kugeln entgegen. Gegner, die zu ihnen geschickte Kugeln berühren, erleiden 30 Feuerschaden." }
