entries[407327] = { ["name"] = "Instabile Essenz", ["text"] = "Unbegrenzte Reichweite\nSofort\nThadrion erfüllt Spielercharaktere mit instabiler Energie, die alle 2 Sek. 11938 Arkanschaden verursacht und mit der Zeit an Intensität gewinnt.\n\nBei Entfernung verschmilzt die Energie kurzzeitig und explodiert dann, was Spielercharakteren innerhalb von 12 Metern 382005 Arkanschaden zufügt\n\nEine verbleibende Spur der Energie springt dann auf einen Spielercharakter in der Nähe über und belegt ihn mit 'Instabile Essenz'." }
