entries[407552] = { ["name"] = "Zeitanomalie", ["text"] = "Wirken in 2 sek.\nRionthus erschafft einen Vortex aus Temporalenergie, der auf ihn zutreibt. Wenn die Anomalie mit Rionthus kollidiert, erhält er einen Schild, der Schaden in Höhe von 20% seiner maximalen Gesundheit absorbiert.\n\nWenn ein Spielercharakter mit der Anomalie kollidiert, verursacht sie 119377 Arkanschaden, wendet ' Zeitfraktur ' an und wird weggestoßen." }
entries[407555] = { ["name"] = "Tarecgosas Abbild", ["text"] = "Wirken in 1.5 sek.\nVerwandelt Euch in Tarecgosas Abbild, wodurch Ihr erhöhte Bewegungsgeschwindigkeit erhaltet und fliegen könnt.\n\"Lebt wohl, Tarecgosa. Geliebte Schwester, Heldin, Schülerin und Lehrerin. Auch ohne Blutsbande werdet Ihr immer Familie für mich sein. Möge Eure Seele ihren Platz unter den Sternen finden.\"\nQuest:\nRhapsodie in Blau" }
